.sbtn-tg:hover{background:rgba(0,136,204,0.18);border-color:rgba(0,136,204,0.55);color:#0088cc;}
.sbtn-ig{background:rgba(225,48,108,0.06);border-color:rgba(225,48,108,0.22);color:rgba(225,48,108,0.85);}
.sbtn-ig:hover{background:rgba(225,48,108,0.18);border-color:rgba(225,48,108,0.55);color:#E1306C;}
.sbtn-icon{width:20px;height:20px;}

/* FOOTER */
footer{border-top:0.5px solid rgba(0,0,0,0.15);padding:48px 20px 32px;position:relative;z-index:10;}
.footer-inner{max-width:var(--max);margin:0 auto;display:grid;grid-template-columns:1fr;gap:28px;}
@media(min-width:700px){.footer-inner{grid-template-columns:1.5fr 1fr 1fr;}}
.f-logo{font-family:"CormorantGaramond",Georgia,serif;font-size:28px;font-weight:700;color:#ffffff;letter-spacing:0.15em;margin-bottom:6px;}
.f-tag{font-size:12px;color:rgba(20,6,0,0.45);line-height:1.7;margin-bottom:18px;}
.f-social{display:flex;gap:10px;}
.f-soc-a{width:36px;height:36px;border-radius:10px;background:rgba(0,0,0,0.08);border:0.5px solid rgba(0,0,0,0.18);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all 0.18s;}
.f-soc-a:hover{background:rgba(0,0,0,0.2);border-color:rgba(0,0,0,0.4);}
.f-soc-a svg{width:17px;height:17px;}
.f-col-title{font-size:11px;letter-spacing:0.2em;text-transform:uppercase;color:#ffffff;font-weight:600;opacity:0.7;margin-bottom:16px;}
.f-link{display:block;font-size:13px;color:rgba(20,6,0,0.5);cursor:pointer;transition:color 0.18s;margin-bottom:10px;text-decoration:none;}
.f-link:hover{color:#ffffff;}
.f-copy{max-width:var(--max);margin:28px auto 0;padding-top:20px;border-top:0.5px solid rgba(0,0,0,0.1);font-size:11px;color:rgba(20,6,0,0.4);letter-spacing:0.06em;text-align:center;}

/* FADE */
.fade-in{opacity:0;transform:translateY(22px);transition:opacity 0.65s ease,transform 0.65s cubic-bezier(.22,1,.36,1);}
.fade-in.show{opacity:1;transform:translateY(0);}
.d1{transition-delay:0.08s;}.d2{transition-delay:0.16s;}.d3{transition-delay:0.24s;}

/* NAV mobile */
@media(max-width:768px){.nav-links{display:none;}.nav-ham{display:flex;}}
</style>
</head>
