<script>
function toggleMenu(){document.getElementById("mobileMenu").classList.toggle("open");}

// PARTICLES
const pC=document.getElementById("pcontainer");
const ptC=["rgba(0,0,0,","rgba(20,6,0,","rgba(10,3,0,"];
for(let i=0;i<60;i++){
  const pt=document.createElement("div");pt.className="pt";
  const s=1+Math.random()*3.5,c=ptC[Math.floor(Math.random()*3)];
  const a=0.07+Math.random()*0.2,dur=10+Math.random()*18,del=Math.random()*15;
  const drift=(Math.random()-0.5)*100,left=Math.random()*100,isC=Math.random()>0.45;
  pt.style.cssText="width:"+s+"px;height:"+s+"px;left:"+left+"%;bottom:-10px;background:"+(isC?c+a+")":"transparent")+";border:"+(isC?"none":"0.5px solid "+c+(a*0.5)+")")+";border-radius:50%;--drift:"+drift+"px;animation-duration:"+dur+"s;animation-delay:-"+del+"s;";
  pC.appendChild(pt);
}

// PLANET PLACEMENT — key fix: properly spaced on all screen sizes
function placePlanets(){
  const ring=document.getElementById("ringWrap");
  const rw=ring.offsetWidth;
  const cx=rw/2,cy=rw/2;
  const pSize=parseFloat(getComputedStyle(document.querySelector(".planet-inner")).width)||52;
  const half=pSize/2;

  // Orbit radii as fraction of ring width
  const R1=rw*0.265; // inner orbit
  const R2=rw*0.42;  // outer orbit

  // 6 planets: alternating inner/outer to maximise spacing
  // Positions: top(R1), upper-right(R2), lower-right(R2), bottom(R1), lower-left(R2), upper-left(R2)
  const cfgs=[
    {r:R1, a:-Math.PI/2},           // p0 top inner
    {r:R2, a:-Math.PI/6},           // p1 upper-right outer  
    {r:R2, a:Math.PI/2+Math.PI/6},  // p2 lower-right outer
    {r:R1, a:Math.PI/2},            // p3 bottom inner
    {r:R2, a:Math.PI+Math.PI/6},    // p4 lower-left outer
    {r:R2, a:-Math.PI-Math.PI/6},   // p5 upper-left outer
  ];

  document.querySelectorAll(".planet").forEach((p,i)=>{
    const c=cfgs[i]||{r:R2,a:0};
    const x=cx+Math.cos(c.a)*c.r-half;
    const y=cy+Math.sin(c.a)*c.r-half;
    p.style.transform="translate("+x+"px,"+y+"px)";
  });
}

window.addEventListener("resize",placePlanets);
// run after fonts/layout settle
setTimeout(placePlanets,60);
setTimeout(placePlanets,300);

// PLANET FLOAT animation
(function(){
  document.querySelectorAll(".planet-inner").forEach((p,i)=>{
    const ph=i*(Math.PI*2/6);
    function tick(time){p.style.transform="translateY("+Math.sin(time*.0008+ph)*5+"px)";requestAnimationFrame(tick);}
    requestAnimationFrame(tick);
  });
})();

// SCROLL FADE
const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add("show");});},{threshold:0.08});
document.querySelectorAll(".fade-in").forEach(el=>obs.observe(el));
setTimeout(()=>{document.querySelectorAll(".fade-in").forEach(el=>{if(el.getBoundingClientRect().top<window.innerHeight)el.classList.add("show");});},100);
</script>
